CREATE VIEW `v_programs_by_month` AS
  SELECT
    DATE(DATE_FORMAT(p.`created_ts`, '%Y-%m-01')) AS `createdAtMonth`,
    p.`status` AS `status`,
    COUNT(p.`id`) AS `programs`,
    CAST(SUM(CASE WHEN p.`status` = 'PUBLISHED' THEN p.`priceCents` END) AS SIGNED) AS `listValue`
  FROM `programs` p
  GROUP BY DATE(DATE_FORMAT(p.`created_ts`, '%Y-%m-01')), p.`status`;

CREATE VIEW `v_programs_by_week` AS
  SELECT
    DATE(DATE_SUB(p.`created_ts`, INTERVAL WEEKDAY(p.`created_ts`) DAY)) AS `createdAtWeek`,
    COUNT(p.`id`) AS `programs`
  FROM `programs` p
  WHERE p.`status` = 'PUBLISHED'
  GROUP BY DATE(DATE_SUB(p.`created_ts`, INTERVAL WEEKDAY(p.`created_ts`) DAY));

CREATE VIEW `v_recent_programs` AS
  SELECT
    COUNT(p.`id`) AS `programs`
  FROM `programs` p
  WHERE p.`created_ts` >= (UTC_TIMESTAMP(3) - INTERVAL 30 DAY);

