CREATE VIEW `v_program_long_weeks` AS
  SELECT
    p.`id` AS `programKey`,
    COUNT(w.`id`) AS `weeks`,
    COALESCE(CAST(SUM(w.`durationMinutes`) AS SIGNED), 0) AS `totalMinutesOrZero`
  FROM `programs` p
  LEFT OUTER JOIN `weeks` w ON p.`id` = w.`programId` AND w.`durationMinutes` >= 60
